{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "Model-Based / Model-Free Mixture",
      "description": "Stage 1 values are computed as a weighted average of model-based and model-free Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "reward_dependent_stickiness",
      "title": "Reward-Dependent Stickiness (Win-Stay/Lose-Shift)",
      "description": "Adds a bonus or penalty to the previously chosen stage 1 action's logits depending on whether the previous trial was rewarded.",
      "params": [
        {
          "name": "p_win",
          "bounds": [-5, 5]
        },
        {
          "name": "p_lose",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "p_current = p_win if last_reward > 0 else p_lose\nlogits_1 = beta_1 * q_net + p_current * stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay_center",
      "title": "Value Decay to Center",
      "description": "Unchosen actions in both stages decay towards a specific center parameter, which is also used to initialize the Q-values.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        },
        {
          "name": "decay_center",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf = np.full(2, decay_center)\nq_stage2_mf = np.full((2, 2), decay_center)\n...\nq_stage1_mf[unchosen_1] = q_stage1_mf[unchosen_1] * (1 - decay_rate) + decay_center * decay_rate\n...\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] = q_stage2_mf[s, a] * (1 - decay_rate) + decay_center * decay_rate",
      "expressible_in_slots": true
    }
  ]
}
